import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0015 — Note giornaliere, template, composer: dettagli (M6-WP3a)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0015-daily-templates-composer-details.md","filePath":"adr/0015-daily-templates-composer-details.md"}'),n={name:"adr/0015-daily-templates-composer-details.md"};function l(r,e,c,d,s,m){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0015-—-note-giornaliere-template-composer-dettagli-m6-wp3a" tabindex="-1">ADR-0015 — Note giornaliere, template, composer: dettagli (M6-WP3a) <a class="header-anchor" href="#adr-0015-—-note-giornaliere-template-composer-dettagli-m6-wp3a" aria-label="Permalink to &quot;ADR-0015 — Note giornaliere, template, composer: dettagli (M6-WP3a)&quot;">​</a></h1><ul><li>Stato: accettata</li><li>Recepito in: <code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.6.6, §3.4.6 (Appendice C.4)</li><li>Contesto: M6-WP3 (prima metà: daily/unique note, template, composer, slash commands, nota casuale).</li></ul><h2 id="decisioni" tabindex="-1">Decisioni <a class="header-anchor" href="#decisioni" aria-label="Permalink to &quot;Decisioni&quot;">​</a></h2><ol><li><strong>Formati data.</strong> Sottoinsieme dei token Moment usati comunemente per i formati di data: <code>YYYY YY Q MMMM MMM MM M DD D Do dddd ddd d HH H hh h mm m ss s A a X x Z ZZ</code> e <code>[letterale]</code>; ogni altro carattere è copiato. Nomi in inglese e italiano (lingua della UI), altro → inglese. Un formato che contiene <code>/</code> annida le note in sottocartelle. La navigazione giorno precedente/successivo interpreta il nome del file con lo stesso formato (<code>ParseDate</code>): formati con token orari non sono interpretabili e la navigazione risponde &quot;non è una nota giornaliera&quot;.</li><li><strong>Variabili template.</strong> <code>{{date}}</code>, <code>{{date:FMT}}</code>, <code>{{time}}</code>, <code>{{time:FMT}}</code>, <code>{{title}}</code>; le variabili sconosciute restano letterali. Per le daily note <code>{{date}}</code> è il giorno della nota, <code>{{time}}</code> l&#39;ora corrente. Un template mancante non blocca la creazione (nota vuota, warning nel log).</li><li><strong>Impostazioni.</strong> <code>.memobrain/daily.json</code> per vault (solo chiavi impostate dall&#39;utente), risolte come le altre: default → config gestita (<code>daily_notes.{folder,format,template}</code>) → utente → chiavi <code>locked</code>. Non c&#39;è nuova voce nella whitelist di <code>ReadConfig</code>: i binding <code>TemplatesAPI.ReadSettings/WriteSettings</code> accedono solo a quel file.</li><li><strong>Libreria di gruppo.</strong> Se <code>templates.library_share_id</code> è nella config e <code>&lt;data&gt;/mounts/&lt;id&gt;/</code> esiste, tutte le note <code>.md</code> del mount sono elencate come sorgente <code>library</code> (riferimento <code>library:&lt;path&gt;</code>), in sola lettura, etichettate col nome del mount. Mount assente → nessun effetto. L&#39;id è validato (solo esadecimali e <code>-</code>) e i path passano da <code>vault.FS</code> (no traversal). Non si controlla lo stato <code>revoked</code>: la copia locale resta usabile finché esiste.</li><li><strong>Composer — unione.</strong> Ordine: (1) scrittura del target (con hash atteso); (2) riscrittura dei link verso la sorgente (<code>links.PlanRedirect</code>/<code>ApplyEdits</code>, stessa logica dei rename, tutto-o-niente); (3) sorgente nel cestino. Fallimento al passo 1: nulla cambia. Al passo 2: le note già riscritte sono ripristinate e il target torna al contenuto originale. Al passo 3: il contenuto è già unito e i link già reindirizzati, nulla va perso; la sorgente resta accanto al target e l&#39;errore lo segnala. Il frontmatter della sorgente non viene unito. Separatore configurabile (titolo <code>##</code>, linea, nessuno). Anteprima &quot;N link in M note&quot; come per il rename.</li><li><strong>Composer — estrazione.</strong> Il backend crea la nuova nota (mai sovrascrive, suffisso numerico) e restituisce il testo sostitutivo (<code>[[nota]]</code> o <code>![[nota]]</code>, percorso completo se il nome è ambiguo); è l&#39;editor a sostituire la selezione, così le modifiche non salvate non vengono mai sovrascritte da disco. Frontmatter copiabile come opzione.</li><li><strong>Slash commands.</strong> Sorgente di completamento CodeMirror con sottoinsieme fisso di voci; usa gli id del registro (<code>editor:bullet</code>, <code>editor:task</code>, <code>template:insert</code>, …) caricato in modo lazy. Non si attiva in code block, codice inline, frontmatter, math, URL, né dentro una parola; disattivabile in impostazioni; mai in editor di sola lettura.</li><li><strong>Sola lettura.</strong> Comandi di creazione disabilitati e binding che rifiutano la scrittura (<code>writable</code>) sui mount <code>viewer</code>.</li></ol><h2 id="conseguenze-note" tabindex="-1">Conseguenze / note <a class="header-anchor" href="#conseguenze-note" aria-label="Permalink to &quot;Conseguenze / note&quot;">​</a></h2><ul><li>Impostazione &quot;Template di ogni nuova nota&quot; (<code>newNoteTemplate</code> in <code>.memobrain/daily.json</code>, vuota per default): <code>createNote</code> espande il template scelto con il titolo della nota (variabili come negli altri template) per ogni nota nuova, anche quelle create da un link a una nota mancante. Un template sparito lascia la nota vuota invece di bloccarne la creazione. Restano a parte il comando &quot;Nuova nota da template&quot;, le note giornaliere e le note uniche, che hanno i propri template.</li><li><code>frontend/wailsjs/go/models.ts</code> rigenerato: in fase di merge va rigenerato di nuovo (<code>make gen-wails</code>).</li></ul>',6)])])}const g=o(n,[["render",l]]);export{u as __pageData,g as default};
